from pathlib import Path
import json,sys,subprocess,time
B=Path(__file__).resolve().parent;R=B.parents[1];data=json.load(open(sys.argv[1]));p=list(map(int,Path(sys.argv[2]).read_text().split()));assert len(p)==26 and sorted(p)==list(range(26));label=sys.argv[3];n=sys.argv[4];geom=json.loads((R/'batches/kryha-wheel-sol61/wheel52.json').read_text());cfg=B/f'{label}-configuration.txt';cfg.write_text(' '.join(map(str,[data['K'][0]]+data['O']+p))+'\n'+'\n'.join(data['ciphertexts_full'][q]for q in (0,1))+'\n');values=geom['adjacent_distances']+data['delta']+[0]*26+[0]*(23*26);t=time.monotonic();run=subprocess.run([str(B/'path-full-skip5'),n,str(B/f'model{n}.tsv'),str(cfg)],input=' '.join(map(str,values)),text=True,capture_output=True,check=True);(B/f'{label}-paths.txt').write_text(run.stdout);(B/f'{label}-timing.json').write_text(json.dumps({'seconds':time.monotonic()-t,'ngram':n,'count':run.stdout.splitlines()[0],'no_truth_input':True},indent=2));print(label,time.monotonic()-t,run.stdout.splitlines()[:2])
